def rates_from_counts(tn: int, fp: int, fn: int,
                      tp: int) -> dict:
    """Print and return precision, recall and F1."""
    precision = tp / (tp + fp)
    recall = tp / (tp + fn)
    f1 = 2 * precision * recall / (precision + recall)
    print("P/R/F1:", round(precision, 4),
          round(recall, 4), round(f1, 4))
    return {"precision": precision, "recall": recall,
            "f1": f1}
